CHROME_DEVTOOLS_AXI_SESSION=tour-ux chrome-devtools-axi open "http://127.0.0.1:8765/index.html" && CHROME_DEVTOOLS_AXI_SESSION=tour-ux chrome-devtools-axi resize 1280 800 && CHROME_DEVTOOLS_AXI_SESSION=tour-ux chrome-devtools-axi eval "localStorage.removeItem('simplify-viewer-tour-v1'); location.reload()" && CHROME_DEVTOOLS_AXI_SESSION=tour-ux chrome-devtools-axi wait 800 && CHROME_DEVTOOLS_AXI_SESSION=tour-ux chrome-devtools-axi eval "
(() => {
  // advance to step 2
  document.getElementById('uiTourNext')?.click();
  const spot = document.getElementById('uiTourSpotlight');
  const sr = spot.getBoundingClientRect();
  const sels = ['.preloaded-row', '#preloadedTrigger', '#uploadBtn', '#epsilonInput', '#deltaInput', '#loadBtn', '.header-baseline'];
  const info = {};
  for (const s of sels) {
    const n = document.querySelector(s);
    if (!n) { info[s] = null; continue; }
    const t = n.closest('label') || n;
    const r = t.getBoundingClientRect();
    info[s] = {tag: t.tagName, class: t.className, top: r.top, left: r.left, w: r.width, h: r.height, bottom: r.bottom};
  }
  info.spotlight = {top: sr.top, left: sr.left, w: sr.width, h: sr.height, bottom: sr.bottom};
  info.step = document.getElementById('uiTourStepLabel')?.textContent;
  // measure vertical padding: content vs spotlight for step 2 targets
  const nodes = ['.preloaded-row','#preloadedTrigger','#uploadBtn'].map(s => document.querySelector(s)).filter(Boolean);
  let top=Infinity, bottom=-Infinity;
  for (const n of nodes) { const r=n.getBoundingClientRect(); top=Math.min(top,r.top); bottom=Math.max(bottom,r.bottom); }
  info.padAbove = top - sr.top;
  info.padBelow = sr.bottom - bottom;
  return JSON.stringify(info, null, 2);
})()
"

